-- Northern Gun Two: five non-environmental and seven environmental NG body armors.
-- 12 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~297-northern-gun-2-armor-b.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- Rifts World Book 34: Northern Gun Two, printed pp.49-60 (row 3 of the
-- northern-gun-2 plan, 2026-11-16). Text layer, page_offset 1. Every M.D.C.
-- by Location block, weight, cost and mobility figure was read off a 110 dpi
-- render of cache pages p050-p061, not the text cache (the cache scrambles the
-- two-column location blocks on pp.51, 53, 54 and 60).
--
-- Five non-environmental suits (Juicer Ultra-Armor, Patrol, Robot Command,
-- NG-A8 Scout, NG-A10 Soldier) and seven environmental ones (NG-A12
-- Anti-Ballistic, A25 Bullfrog, Deep Zone Walker, Mud-Skipper, Peacekeeper,
-- Stalker Suit, Trekker Pilot): 12 rows. The other suits on these pages are
-- held already and are not touched here.
--
-- Not rows: the Features Common to All Northern Gun EBA list (p.52) is folded
-- into each EBA's description. mdc is the main body; locations and mobility
-- penalties are in the description, which the catalog has no columns for.
--
-- Page oddities, kept as printed:
-- - The JBA330 and JBA335 share one heading and one row; mdc, weight and cost
--   store the JBA330 (55, 15 lbs, 29,000) and the description carries the
--   JBA335 (70, 20 lbs, 35,000). The mobility line prints "JBA33" and the
--   M.D.C. line "JAB335"; both read as the two models.
-- - Trekker Pilot EBA starts on p.59 and its stats and cost print on p.60.
-- - Peacekeeper mdc stores the basic 40; 85 with the tactical plates.
-- - Stalker Suit stores the 11,100 list price; the book says it often sells
--   for double.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-jba330-juicer-ultra-armor', 'NG-JBA330 and JBA335 Juicer Ultra-Armor', 'rifts', 'armor', 15, 29000, 'JBA330 medium 29,000; JBA335 heavy 35,000. Customization (spikes, studs, chains, paint, insignia) usually 500-3,000 extra; Juicer Rocket Boots 25,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 55, 'The classic Juicer armor look rebuilt with modern M.D.C. micro-fiber and hidden lightweight plating, also called Juicer Modern or Juicer Mod. The helmet is the Bullet Ride Armor helmet with a Mohawk crest, and takes every Ride Armor helmet feature and option. Two weights that look identical. JBA330 medium: 15 lbs (6.7 kg); helmet 35, each arm 19, each leg 30, main body 55; no movement penalty. JBA335 heavy: 20 lbs (9 kg); helmet 35, each arm 25, each leg 40, main body 70; -5% to Climb, Prowl, Swim, Acrobatics, Gymnastics and similar skills, doubled to -10% for anyone who is not a Juicer, Crazy or comparably strong and agile. Non-environmental. Stored M.D.C., weight and cost are the JBA330''s.', 'Rifts World Book 34: Northern Gun Two p.49', NULL),
  ('ng-patrol-armor', 'NG Patrol Armor', 'rifts', 'armor', 10, 15500, 'Good to excellent availability. Custom striping, patches and markings at modest extra cost.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 32, 'Very light armor cut as a uniform jumpsuit or fatigues, with M.D.C. polycarbonate plates and padding hidden in the cloth at chest, belly, arms, legs, elbows and knees. Sold in many colors to militias, mercenary outfits, police and highway patrol. The padded helmet leaves the face open so townsfolk can see the officer; a clear plastic visor (4 M.D.C.) is supplied but seldom worn. Helmet 20; each arm 14; each leg 18; main body 32. Excellent mobility, no movement penalty. Non-environmental: no cooling and no oxygen supply.', 'Rifts World Book 34: Northern Gun Two p.50', NULL),
  ('ng-robot-command-armor', 'NG Robot Command Armor', 'rifts', 'armor', 18, 25500, 'Good to excellent availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 55, 'Armor for robot and vehicle pilots (RC armor): solid ceramic plating over chest, belly and shoulders and a hard helmet, while the arms and legs get only M.D.C. cloth and padding so hands and feet move freely at the controls. Helmet 35; each arm 11; each leg 14; main body 55. Piloting skills unpenalized; Climb, Rappel, Prowl, Acrobatics and the like at -5%; Swim at -10%. The command helmet carries a 5 mile (8 km) two-way radio, language translator, radiation detector, HUD, self-darkening polarized visor, air filter and 8 minutes of emergency oxygen. Not full environmental: no cooling system.', 'Rifts World Book 34: Northern Gun Two p.50-51', NULL),
  ('ng-a8-scout-armor', 'NG-A8 Scout Armor', 'rifts', 'armor', 12, 28000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'A light suit developed from the Huntsman pattern that adds protection while staying nimble, and now outsells the Plastic-Man and Huntsman. Bought by Juicers, Psi-Stalkers, Wilderness Scouts, thieves, assassins and city operatives. Head/helmet 35; each arm 25; each leg 40; main body 50. Excellent mobility (Climb, Prowl, Swim, Acrobatics and the like at -5%). Non-environmental: no cooling and no oxygen supply.', 'Rifts World Book 34: Northern Gun Two p.51', NULL),
  ('ng-a10-soldier-body-armor', 'NG-A10 Soldier Body Armor', 'rifts', 'armor', 18, 36000, 'Giant-size suits 50,000-75,000 depending on size.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 72, 'Sturdy, plain olive-drab armor issued to Ishpeming''s forces and sold abroad: composite plates strapped over a padded flexible suit much like Bushman armor, with no markings. Head/helmet 50; each arm 35; each leg 45; main body 72. Good mobility (Climb, Prowl, Swim, Acrobatics and the like at -10%). A giant-size version fits Grackle Tooth, Brodkil, Ogres, Trolls and other big humanoids: 44 lbs (20 kg), main body 110 and every other location +20, with a further -5% to Climb, Prowl and similar skills. Non-environmental: no cooling and no oxygen supply.', 'Rifts World Book 34: Northern Gun Two p.51', NULL),
  ('ng-a12-anti-ballistic-armor', 'NG-A12 Anti-Ballistic Armor', 'rifts', 'armor', 25, 61000, 'Fair availability. Custom colors, logos and insignia from a couple of thousand up to 12,000 credits. Barred from the Robodome.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 80, 'An experimental environmental suit designed by NG engineer Burt Turner. A loose outer mantle spreads the force of a hit across the whole suit, and pressurized air inside cushions the wearer and keeps gas, toxins and germs out even after a breach. The suit takes half damage from all kinetic attacks (punches, kicks, falls, impacts, explosions), halved again on a successful roll with impact; the wearer takes only 20% of normal fall and crash damage. Olive, tan, white, grey or camouflage. Head/helmet 40; each arm 35; each leg 45; main body 80. Fair mobility: -10% to Climb, -15% to Prowl, Acrobatics and similar skills. Has the standard NG EBA features: sealed environmental system to 350 ft (107 m), computer life support with cooling and five hours of oxygen, heat shielding to 200 C, basic radiation shielding, polarized visor, 5-10 mile (8-16 km) radio, usually a HUD, and back connectors for packs. Sales have been poor.', 'Rifts World Book 34: Northern Gun Two p.52-53', NULL),
  ('ng-a25-bullfrog-eba', 'NG A25 Aquatic Bullfrog Combat & Exploration EBA', 'rifts', 'armor', 24, 62000, 'Fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 75, 'An armored diving suit so heavily plated it is mistaken for power armor: ceramic and polymer plates over shins, feet, knees, thighs, belly, chest, forearms and shoulders on an M.D.C. fabric body. Used by navies, pirates, salvagers and Great Lakes explorers. Fold-out swim fins, water seals and drain plugs in hands and feet; a sealed helmet with a top spotlight (100 ft/30.5 m underwater, double on the surface); depth gauge and compass with alarms near the depth limit or on low or leaking air; 5 mile (8 km) underwater radio; a vital-signs monitor that alerts teammates; a Vibro-Knife (1D6 M.D.) sheathed at the shoulder; 12 hours of air (double at rest). Depth limit 500 ft (152 m). Head/helmet 40; each arm 25; each leg 45; oxygen backpack 40; main body 75. Fair mobility: -10% to Climb, Prowl, Acrobatics and similar skills, no Swim penalty, +6 swimming Spd. Plus the standard NG EBA features (life support, heat and radiation shielding, polarized visor, back connectors).', 'Rifts World Book 34: Northern Gun Two p.53', NULL),
  ('ng-deep-zone-walker-eba', 'NG Aquatic Deep Zone Walker Deep Sea EBA', 'rifts', 'armor', 41, 65000, 'Poor availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 90, 'A deep-sea research suit good to one mile (1.6 km) down. It cannot swim and has no propulsion: it sinks or is set down by a submersible and walks the bottom, and a ballast float raises it slowly so the wearer avoids the bends. A forehead light band (30 ft/9.1 m) and usually a handheld spotlight (100 ft/30.5 m underwater, double on the surface); depth gauge and compass with alarms near the depth limit or on low or leaking air; 5 mile (8 km) underwater radio; vital-signs monitor; Vibro-Knife (1D6 M.D.) at the shoulder; 12 hours of air (double at rest). Head/helmet 40; each arm 45; each leg 60; oxygen backpack 40; main body 90. Poor mobility: -15% to Climb, Prowl, Acrobatics and similar skills, -30% to Swim. Plus the standard NG EBA features (life support, heat and radiation shielding, polarized visor, back connectors).', 'Rifts World Book 34: Northern Gun Two p.53-54', NULL),
  ('ng-mud-skipper-eba', 'NG Aquatic Mud-Skipper Diving EBA', 'rifts', 'armor', 18, 37000, 'Fair availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'An armored SCUBA wet suit that trades plating for freedom of movement. One button inflates an emergency float that carries the diver up slowly and holds him at the surface, and switches on a homing beacon. Fold-out fins, water seals and drain plugs as on the Bullfrog; 8 hours of air (double at rest). Depth limit 220 ft (67 m). Head/helmet 20; each arm 18; each leg 35; oxygen backpack 20; main body 50. Good mobility: -5% to Climb, Prowl, Acrobatics and similar skills, no Swim penalty, +3 swimming Spd. Has all the standard NG EBA features (life support, heat and radiation shielding, polarized visor, helmet radio, back connectors).', 'Rifts World Book 34: Northern Gun Two p.54', NULL),
  ('ng-peacekeeper-eba', 'NG Peacekeeper Body Armor', 'rifts', 'armor', 16, 40000, 'Includes one monitoring unit in a briefcase-sized case. Radio signal booster (+50% range) 5,000. Used suits sell for 28,000-34,000.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'Modular environmental armor sold mostly to police and military police. Day to day it is a light suit that stops S.D.C. weapons and light Mega-Damage; when trouble comes, tactical plates clip on in 1D4 melee actions and roughly double its protection, adding 11 lbs (5 kg). A built-in bio-monitor tracks the wearer''s vital signs and, if he is knocked out, badly hurt or the armor is stripped off, radios a call for backup and a homing signal to a set command post. Radio range about 12 miles (19 km) in cities and 30 miles (48 km) in the open. Head/helmet 50; each arm 25 (50 with tactical plates); each leg 30 (55); main body 40 (85). Good mobility: -5% to Climb, Prowl, Acrobatics and similar skills, -15% with the tactical plates. Plus the standard NG EBA features (life support, heat and radiation shielding, polarized visor, back connectors). Also popular with Rogue Scientists and explorers.', 'Rifts World Book 34: Northern Gun Two p.57-58', NULL),
  ('ng-stalker-suit', 'NG Stalker Suit', 'rifts', 'armor', 3, 11100, 'List price; poor availability outside Ishpeming, so it often sells for twice that.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 12, 'An experimental black skin-tight infiltration suit of M.D.C. polymer weave with a few small plates and pads, worn under clothes or other armor. It covers everything but the head; a separate light helmet (typically 30 or 35 M.D.C.) is suggested. With an EBA helmet and a life-support backpack (2 hours of oxygen) attached it becomes fully environmental. Its fabric spreads out body heat: thermal detection of the wearer is at -20% to Sensory Equipment. Main body 12; each leg 7; each arm 5. No movement penalties at all. Takes 1D4+2 minutes to put on or take off, and many find it too tight. Favored by spies, assassins, cat-burglars and special forces, and by some pilots, scientists and medics.', 'Rifts World Book 34: Northern Gun Two p.58-59', NULL),
  ('ng-trekker-pilot-eba', 'NG Trekker Pilot EBA', 'rifts', 'armor', 18, 30500, 'Good to excellent availability.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'Environmental armor for explorers, hovercycle and truck drivers, cargo haulers and pilots: strong protection on chest and belly with shoulder plates, and M.D.C. fabric, padding and light hidden plates on arms and legs so they move freely at the controls, on horseback or on foot. The helmet has a clear faceplate for a wide field of view. Helmet 25; each arm 16; each leg 22; main body 50. Piloting skills unpenalized; Climb, Rappel, Prowl, Acrobatics and the like at -5%; Swim at -10%. Plus the standard NG EBA features (sealed life support with five hours of oxygen, heat and radiation shielding, helmet radio, back connectors).', 'Rifts World Book 34: Northern Gun Two p.59-60', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 gear rows are in' AS assertion, count(*) AS got, 12 AS want
  FROM gear WHERE slug IN ('ng-jba330-juicer-ultra-armor', 'ng-patrol-armor', 'ng-robot-command-armor', 'ng-a8-scout-armor', 'ng-a10-soldier-body-armor', 'ng-a12-anti-ballistic-armor', 'ng-a25-bullfrog-eba', 'ng-deep-zone-walker-eba', 'ng-mud-skipper-eba', 'ng-peacekeeper-eba', 'ng-stalker-suit', 'ng-trekker-pilot-eba') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~297-northern-gun-2-armor-b.sql');
